<?php
require_once __DIR__.'/auth.php';admin_required();$msg='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';
if($action==='delete'){$s=$pdo->prepare("DELETE FROM products WHERE id=?");$s->execute([(int)$_POST['id']]);$msg='Product deleted.';}
if($action==='save'){
$id=(int)($_POST['id']??0);$name=trim($_POST['name']??'');$cat=(int)($_POST['category_id']??0);$price=(float)($_POST['price']??0);$stock=(int)($_POST['stock']??0);$desc=trim($_POST['description']??'');$featured=isset($_POST['featured'])?1:0;$active=isset($_POST['active'])?1:0;$image=null;
if($name===''||$cat<1||$price<0||$stock<0)$error='Please enter valid product details.';
else{
if(!empty($_FILES['image']['name'])){$f=$_FILES['image'];$allowed=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);if($f['error']!==UPLOAD_ERR_OK||!isset($allowed[$mime])||$f['size']>4*1024*1024)$error='Upload JPG, PNG or WEBP image up to 4 MB.';else{$image=bin2hex(random_bytes(12)).'.'.$allowed[$mime];if(!move_uploaded_file($f['tmp_name'],__DIR__.'/../uploads/'.$image)){$error='Image upload failed.';$image=null;}}}
if(!$error){$slug=strtolower(trim(preg_replace('/[^a-z0-9]+/i','-',$name),'-')).'-'.substr(bin2hex(random_bytes(3)),0,6);
if($id){if($image){$s=$pdo->prepare("UPDATE products SET category_id=?,name=?,description=?,price=?,stock=?,image=?,is_featured=?,is_active=? WHERE id=?");$s->execute([$cat,$name,$desc,$price,$stock,$image,$featured,$active,$id]);}else{$s=$pdo->prepare("UPDATE products SET category_id=?,name=?,description=?,price=?,stock=?,is_featured=?,is_active=? WHERE id=?");$s->execute([$cat,$name,$desc,$price,$stock,$featured,$active,$id]);}$msg='Product updated.';}
else{$s=$pdo->prepare("INSERT INTO products(category_id,name,slug,description,price,stock,image,is_featured,is_active) VALUES(?,?,?,?,?,?,?,?,?)");$s->execute([$cat,$name,$slug,$desc,$price,$stock,$image,$featured,$active]);$msg='Product added.';}
}}
}
}
$cats=$pdo->query("SELECT * FROM categories ORDER BY name")->fetchAll();$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare("SELECT * FROM products WHERE id=?");$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}
$products=$pdo->query("SELECT p.*,c.name category_name FROM products p JOIN categories c ON c.id=p.category_id ORDER BY p.created_at DESC")->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Products | AS NILORA</title><link rel="stylesheet" href="<?= e(url('assets/css/style.css')) ?>"></head><body><main class="section"><a href="<?= e(url('admin/index.php')) ?>">← Dashboard</a><h1>Manage products</h1><?php if($msg): ?><p class="success-msg"><?= e($msg) ?></p><?php endif; ?><?php if($error): ?><p class="form-error"><?= e($error) ?></p><?php endif; ?><form method="post" enctype="multipart/form-data" class="admin-form"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?= (int)($edit['id']??0) ?>"><h2><?= $edit?'Edit product':'Add a product' ?></h2><label>Product name<input name="name" required value="<?= e($edit['name']??'') ?>"></label><label>Category<select name="category_id" required><?php foreach($cats as $c): ?><option value="<?= (int)$c['id'] ?>" <?= (int)($edit['category_id']??0)===(int)$c['id']?'selected':'' ?>><?= e($c['name']) ?></option><?php endforeach; ?></select></label><label>Price (₹)<input type="number" name="price" min="0" step=".01" required value="<?= e((string)($edit['price']??'')) ?>"></label><label>Stock quantity<input type="number" name="stock" min="0" required value="<?= e((string)($edit['stock']??0)) ?>"></label><label>Description<textarea name="description" rows="3"><?= e($edit['description']??'') ?></textarea></label><label>Product photo (JPG/PNG/WEBP, max 4 MB)<input type="file" name="image" accept="image/jpeg,image/png,image/webp"></label><label class="radio-line"><input type="checkbox" name="featured" <?= !empty($edit['is_featured'])?'checked':'' ?>> Feature on homepage</label><label class="radio-line"><input type="checkbox" name="active" <?= !isset($edit['is_active'])||$edit['is_active']?'checked':'' ?>> Visible in store</label><button class="btn btn-gold">Save product</button><?php if($edit): ?><a href="<?= e(url('admin/products.php')) ?>">Cancel edit</a><?php endif; ?></form><h2>All products</h2><div class="table-wrap"><table><tr><th>Product</th><th>Category</th><th>Price</th><th>Stock</th><th>Actions</th></tr><?php foreach($products as $p): ?><tr><td><?= e($p['name']) ?></td><td><?= e($p['category_name']) ?></td><td><?= money($p['price']) ?></td><td><?= (int)$p['stock'] ?></td><td><a href="?edit=<?= (int)$p['id'] ?>">Edit</a> <form method="post" class="inline-form" onsubmit="return confirm('Delete this product?')"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?= (int)$p['id'] ?>"><button class="link-button">Delete</button></form></td></tr><?php endforeach; ?></table></div></main></body></html>
